-- generated by keybinds-gen — auto-loaded from plugin/
-- do not edit; re-run `sudo keybinds-gen apply`
local function term(cmd)
  vim.cmd("botright split | terminal " .. cmd)
  vim.cmd("startinsert")
end

-- the popup lives in Noctalia now
vim.keymap.set("n", "<leader>?k", function()
  vim.fn.system("keybinds-gen popup")
end, { desc = "Keybind popup (Noctalia)" })

-- full sheets still usable inside nvim
for _, spec in ipairs({
  { "m", "formulas maths", "Maths formulas" },
  { "p", "formulas physics", "Physics formulas" },
  { "x", "formulas latex", "LaTeX notation" },
}) do
  vim.keymap.set("n", "<leader>?" .. spec[1], function()
    term("keybinds " .. spec[2])
  end, { desc = spec[3] })
end

-- run the current file in a terminal split
vim.keymap.set("n", "<leader>rr", function()
  term("devshell run %:p")
end, { desc = "Run current file" })
vim.keymap.set("n", "<leader>rs", function()
  term("devshell scratch")
end, { desc = "Open language scratch" })
